import { PokemonGenerator } from "../module/actor/pokemon/generator.js"
import { CompendiumBrowser } from "../module/apps/compendium-browser/index.js"
import { MigrationSummary } from "../module/apps/migration-summary.js"
import { TokenPanel } from "../module/apps/token-panel.js"
import { StatusEffects } from "../module/canvas/status-effect.js"
import { MigrationList } from "../module/migration/index.js"
import { MigrationRunner } from "../module/migration/runner/index.js"
import { EffectTracker } from "../module/system/effect-tracker.js"
import { getSpeciesData } from "../module/system/index.js"
import { findItemInCompendium, querySpeciesCompendium } from "../util/misc.js"
import { resolveInjectedProperties, resolveValue } from "../util/value-resolver.js"
import { dexSync } from "./macros/dex-sync.js"
import { pokedex } from "./macros/pokedex.js"
import { changeRotomForm } from "./macros/rotom-form-change.js"
import { TypeMatrix } from "../module/apps/type-matrix.js";
import { Weather } from "../module/apps/weather.js";
import { PTUPokemonTrainingSheet } from "../module/apps/pokemon-training/index.js";

const GamePTU = {
    onInit() {
        const initData = {
            species: {
                get: getSpeciesData,
                query: querySpeciesCompendium,
                generator: PokemonGenerator
            },
            item: {
                get: (name, type) => findItemInCompendium({ type, name }),
            },
            StatusEffects,
            forms: {
                massGenerator: undefined
            },
            effectTracker: new EffectTracker(),
            resolver: {
                resolveInjectedProperties,
                resolveValue
            },
            migration: {
                MigrationList,
                MigrationRunner,
                MigrationSummary
            },
            weather: Weather,
            pokemonTraining: PTUPokemonTrainingSheet,
            macros: {
                changeRotomForm,
                pokedex,
                dexSync,
                initializeWorldNotes: (async () => {
                    if (game.folders.getName("Actor Notes")) {
                        return game.settings.set("ptu", "worldNotesFolder", game.folders.getName("Actor Notes").id)
                    }

                    const folder = await Folder.create({ name: "Actor Notes", type: "JournalEntry" });
                    return game.settings.set("ptu", "worldNotesFolder", folder.id)
                }),
                openPokemonTraining: (actor) => {
                    if (!actor) {
                        if (game.user.character === null) {
                            ui.notifications.error("No Character was set for this user.", { localize: true });
                            return;
                        }
                        actor = game.user.character;
                    }
                    new PTUPokemonTrainingSheet({actor}).render(true);
                }
            },
            tokenPanel: new TokenPanel()
        }

        Weather._initializeGlobalEffects();

        game.ptu = foundry.utils.mergeObject(game.ptu ?? {}, initData)

        CONFIG.PTU.data.typeEffectiveness = game.settings.get("ptu", "type.typeEffectiveness") ?? CONFIG.PTU.data.typeEffectiveness;
    },
    onSetup() {},
    onReady() {
        game.ptu.compendiumBrowser = new CompendiumBrowser();
        game.ptu.typeMatrix = new TypeMatrix()

        if (game.user.isGM) {
            if (!game.settings.get("ptu", "worldNotesFolder")) {
                game.ptu.macros.initializeWorldNotes();
            }
            // Else if necessary since initializeWorldNotes is async and we don't want to wait for it
            else if (game.folders.get(game.settings.get("ptu", "worldNotesFolder")) === null) {
                game.ptu.macros.initializeWorldNotes();
            }
        }

        // Reset pokemon that have reloadOnReady marked as true
        // This is due to having a temporary species override
        game.actors.filter(a => a.type === "pokemon" && a.reloadOnReady).forEach(a => a.reset())
    }
}

export { GamePTU }

export function dexSync() {
    ui.notifications.info("Syncing Dexes...");
    let owned = new Set();
    let seen = new Set();
    let updates = [];
    for (const user of game.users.values()) {
        const character = user.character;
        if (!character) continue;
        if (character.type != "character") continue;

        owned = new Set([...owned, ...character.system.dex.owned]);
        seen = new Set([...seen, ...character.system.dex.seen]);
        updates.push({ _id: character.id });
    }
    seen = seen.filter(s => !owned.has(s));

    if(updates.length > 0) Actor.updateDocuments(updates.map(({ _id }) => ({ _id, "system.dex.seen": [...seen], "system.dex.owned": [...owned] })));
    ui.notifications.info("Syncing Dexes Complete!");
}

export function pokedex() {
    const species = game.user.targets.first()?.actor?.species;
    if (!species) return ui.notifications.error("Please target a pokemon");
    species.sheet.render(true)

    const dex = game.user.character?.system?.dex;
    if (!dex) return;
    const seen = [...dex.seen, species.slug];
    return game.user.character.update({ "system.dex.seen": seen });
}

export function changeRotomForm() {
    const actor = canvas.tokens.controlled[0]?.actor;
    if (!actor?.species?.slug.startsWith("rotom")) return ui.notifications.error("Please select your Rotom on the canvas before running this macro.");

    const change = async (forme) => {
        const notifId = ui.notifications.info("Updating rotom...")
        const [species, move] = await (async () => {
            switch (forme) {
                case "normal": return [await game.ptu.item.get("rotom-normal", "species"), null]
                case "fan": return [await game.ptu.item.get("rotom-fan", "species"), await game.ptu.item.get("air-slash", "move")]
                case "frost": return [await game.ptu.item.get("rotom-frost", "species"), await game.ptu.item.get("blizzard", "move")]
                case "heat": return [await game.ptu.item.get("rotom-heat", "species"), await game.ptu.item.get("overheat", "move")]
                case "mow": return [await game.ptu.item.get("rotom-mow", "species"), await game.ptu.item.get("leaf-storm", "move")]
                case "wash": return [await game.ptu.item.get("rotom-wash", "species"), await game.ptu.item.get("hydro-pump", "move")]
            }
        })();
        if (!species) return ui.notifications.error("Could not find rotom species");
        if (actor.species.slug === species.slug) return ui.notifications.warn("Cancelled update as no changes were detected.");
        const image = species.getImagePath({ shiny: !!actor.system.shiny });

        const newSize = (() => {
            const size = species.system.size.sizeClass;
            switch (size) {
                case "Tiny": return { width: 0.5, height: 0.5 };
                case "Small": return { width: 1, height: 1 };
                case "Medium": return { width: 1, height: 1 };
                case "Large": return { width: 2, height: 2 };
                case "Huge": return { width: 3, height: 3 };
                case "Gigantic": return { width: 4, height: 4 };
                default: return { width: 1, height: 1 };
            }
        })();

        const toCreate = [species.toObject()];

        if (actor.species.slug == "rotom-normal") {
            toCreate.push(move.toObject());
        }
        if (actor.species.slug != "rotom-normal") {
            const moveSlug = (() => {
                switch (actor.species.system.form) {
                    case "fan": return "air-slash";
                    case "frost": return "blizzard";
                    case "heat": return "overheat";
                    case "mow": return "leaf-storm";
                    case "wash": return "hydro-pump";
                }
            })();
            const item = actor.itemTypes.move.find(m => m.slug == moveSlug);
            if (item) await actor.deleteEmbeddedDocuments("Item", [item.id]);
            if (move) toCreate.push(move.toObject());
        }

        await actor.createEmbeddedDocuments("Item", toCreate);
        await actor.update({
            img: image,
            "prototypeToken.texture.src": image,
            "prototypeToken.width": newSize.width,
            "prototypeToken.height": newSize.height
        });
        for (const token of actor.getActiveTokens()) {
            await token.document.update({
                "texture.src": image,
                "width": newSize.width,
                "height": newSize.height
            });
        }
        ui.notifications.remove(notifId);
    }

    const d = new Dialog({
        title: "Rotom Form Change",
        content: "What form should rotom change into?",
        buttons: {
            normal: { label: "Normal", callback: () => change("normal") },
            fan: { label: "Fan", callback: () => change("fan") },
            frost: { label: "Frost", callback: () => change("frost") },
            heat: { label: "Heat", callback: () => change("heat") },
            mow: { label: "Mow", callback: () => change("mow") },
            wash: { label: "Wash", callback: () => change("wash") }
        }
    })
    d.render(true);
}

class TypeMatrix extends FormApplication {
    constructor(object, options) { 
        super(object, options);
        this.cache = {};
    }

    static get defaultOptions() {
        const options = super.defaultOptions;
        options.classes.push("ptu-settings-menu");

        return foundry.utils.mergeObject(options, {
            title: "PTU.TypeMatrix.Title",
            template: "systems/ptu/static/templates/config/settings/types.hbs",
            id: "type-matrix",
            width: "auto",
            height: "auto",
            resizable: true,
            submitOnChange: false,
            closeOnSubmit: false,
        });
    }

    async getData() {
        const data = await super.getData();

        if (this.cache["types"] === undefined) {
            const types = game.settings.get("ptu", "type.typeEffectiveness") || this.constructor.settings.typeEffectiveness.default;
            this.cache["types"] = types;
        }

        const typeEffectiveness = foundry.utils.duplicate(this.cache["types"]);
        delete typeEffectiveness.Untyped;

        let typeLength = Object.keys(typeEffectiveness).length + 1;
        if(!game.settings.get("ptu", "homebrew.nuclearType") && typeEffectiveness["Nuclear"]) typeLength--;
        if(!game.settings.get("ptu", "homebrew.shadowType") && typeEffectiveness["Shadow"]) typeLength--;

        return {
            ...data,
            typeEffectiveness,
            types: Object.keys(this.cache["types"].Untyped.effectiveness),
            typeLength,
            readOnly: true
        }
    }

    activateListeners($html) {
        $html.find(".type").on("mouseover", event => {
            const { offensive, defensive } = event.currentTarget.dataset;
            if (!offensive || !defensive) return;

            $html.find(`.type[data-offensive="${offensive}"]`).addClass("highlight-x");
            $html.find(`.type[data-defensive="${defensive}"]`).addClass("highlight-y");
        });

        $html.find(".type").on("mouseout", event => {
            const { offensive, defensive } = event.currentTarget.dataset;
            if (!offensive || !defensive) return;

            $html.find(`.type[data-offensive="${offensive}"]`).removeClass("highlight-x");
            $html.find(`.type[data-defensive="${defensive}"]`).removeClass("highlight-y");
        });
    }
}

export { TypeMatrix }

export async function findItemInCompendium({ type, name, compendium }) {
    if (!type || !name) return undefined;
    const pack = (() => {
        if (game.packs.get(compendium)) return game.packs.get(compendium);
        switch (type) {
            case "move": return game.packs.get("ptu.moves");
            case "ability": return game.packs.get("ptu.abilities");
            case "capability": return game.packs.get("ptu.capabilities");
            case "species": return game.packs.get("ptu.species");
            case "item": return game.packs.get("ptu.items");
            case "edge": return game.packs.get("ptu.edges");
            case "feat": return game.packs.get("ptu.feats");
            case "effect": return game.packs.get("ptu.effects");
            default: throw new Error(`Unknown type: ${type}`);
        }
    })();

    const find = (items) => {
        return items?.find((item) => item.slug === sluggify(name) || item.name === name);
    }

    const indexed = find(pack.contents);
    if (indexed) return indexed;
    return find(await pack.getDocuments());

}

import { RuleElementPTU, isBracketedValue } from "./base.js";

export class TemporarySpeciesRuleElement extends RuleElementPTU {
    constructor(data, item, options = {}) {
        const { species, uuid } = data;
        super(data, item, options);

        if(typeof species === "object") {
            if(species instanceof CONFIG.PTU.Actor.documentClasses.pokemon) this.species = species;
            else if(species.type === "pokemon") this.species = Actor.create(species, {temporary: true});
        }

        if(!species && typeof uuid === "string") {
            this.uuid = uuid;
            this.species = fromUuidSync(uuid);
            if(!this.species.system && uuid.startsWith("Compendium.")) fromUuid(uuid).then(actor => this.species = actor);
        }
    }

    /** @override */
    beforePrepareData() {
        if(!this.species) return this.failValidation("Missing species field");
        this.actor.synthetics.speciesOverride.species = this.species;
    }
}

import { RuleElementPTU } from "./base.js";

export class TypeOverwriteRuleElement extends RuleElementPTU {
  constructor(data, item, options = {}) {
    const { value, overwrite } = data;
    super(data, item, options);

    this.value = value;
    this.overwrite = overwrite;
  }

  /** @override */
  afterPrepareData() {
    const type = this.resolveInjectedProperties(this.value);
    const isArray = Array.isArray(type);
    if (isArray && type.some(t => typeof t !== "string")) return this.failValidation("Invalid value field");
    if (!isArray && typeof type !== "string") return this.failValidation("Invalid value field");

    if (!this.test()) return;

    const typeSet = isArray ? new Set(type.flatMap(v => v.split(','))) : new Set([type].flatMap(v => v.split(',')));
    const realTypes = typeSet.map(t => t.trim()).filter(t => !!t && CONFIG.PTU.data.typeEffectiveness[t]);

    if (this.overwrite) {
      for(const type of this.actor.types) {
        delete this.actor.rollOptions.all[`self:types:${type.toLowerCase()}`];
      }
      for (const type of realTypes) {
        this.actor.rollOptions.all[`self:types:${type.toLowerCase()}`] = true;
      }
      return this.actor.synthetics.typeOverride.typing = [...realTypes]
    }

    if (!this.actor.synthetics.typeOverride.typing) {
      this.actor.synthetics.typeOverride.typing = [];
    }
    this.actor.synthetics.typeOverride.typing.push(...realTypes);
    for(const type of realTypes) {
      this.actor.rollOptions.all[`self:types:${type.toLowerCase()}`] = true;
    }
  }
}

import { RuleElementPTU, isBracketedValue } from "./base.js";

export class TokenImageRuleElement extends RuleElementPTU {
    constructor(data, item, options = {}) {
        const { value, scale, tint, alpha } = data;
        super(data, item, options);

        if (typeof value === "string" || isBracketedValue(value)) {
            this.value = value;
        } else {
            this.value = null;
        }

        if (typeof scale === "number" && scale > 0) {
            this.scale = scale;
        }

        if (typeof tint === "string") {
            this.tint = Color.from(tint).toString();
        }

        if (typeof alpha === "number") {
            this.alpha = alpha;
        }
    }

    /** @override */
    afterPrepareData() {
        let src = this.value;
        if (!this.#srcIsValid(src)) src = this.resolveValue(this.value, 0, {evaluate: false});

        if (!this.test()) return;

        const texture = {};
        if (this.#srcIsValid(src)) {
            texture.src = src;
        }
        if (this.scale) {
            texture.scaleX = this.scale;
            texture.scaleY = this.scale;
        }

        if (this.tint) {
            texture.tint = this.tint;
        }

        if (typeof this.alpha === "number") {
            this.actor.synthetics.tokenOverrides.alpha = this.alpha;
        }

        this.actor.synthetics.tokenOverrides.texture = texture;
    }

    #srcIsValid(src) {
        if (typeof src !== "string") return false;
        if (src.includes("{")) return false;
        const extension = /(?<=\.)([a-z0-9]{3,4})(\?[a-zA-Z0-9]+)?$/i.exec(src)?.at(1);
        return !!extension && (extension in CONST.IMAGE_FILE_EXTENSIONS || extension in CONST.VIDEO_FILE_EXTENSIONS);
    }
}

import { PTUItem } from "../../../item/index.js";
import { MigrationList } from "../../../migration/index.js";
import { MigrationRunner } from "../../../migration/runner/index.js";
import {compendiumItemIdentity} from '../../../../util/preservation.js';
import { RuleElementPTU } from "../base.js";
import {isStarterTrainingGrant, hasStarterTraining} from '../../../../util/starter-training.js';
import {isExcludedContent} from '../../../../util/content-scope.js';

class GrantItemRuleElement extends RuleElementPTU {
    constructor(source, item, options = {}) {
        super(source, item, options);

        if (this.reevaluateOnUpdate) {
            this.replaceSelf = false;
            this.allowduplicate = false;
        }

        this.onDeleteActions = this.#getOnDeleteActions(source);
    }

    /** @override */
    static defineSchema() {
        return {
            ...super.defineSchema(),
            uuid: new foundry.data.fields.StringField({ required: true, nullable: false, blank: false, initial: undefined }),
            flag: new foundry.data.fields.StringField({ required: true, nullable: true, initial: null }),
            reevaluateOnUpdate: new foundry.data.fields.BooleanField({ required: false, nullable: false, initial: false }),
            replaceSelf: new foundry.data.fields.BooleanField({ required: false, nullable: false, initial: false }),
            allowduplicate: new foundry.data.fields.BooleanField({ required: false, nullable: false, initial: true }),
            onDeleteActions: new foundry.data.fields.ObjectField({ required: false, nullable: false, initial: undefined }),
            overwrites: new foundry.data.fields.ObjectField({ required: false, nullable: false, initial: undefined })
        };
    }

    static ON_DELETE_ACTIONS = ["cascade", "detach", "restrict"];

    get grantedId() {
        return this.item.flags.ptu?.itemGrants?.[this.flag]?.id ?? this.item.flags.ptu?.itemGrants?.[this.flag?.replace(/\d{1,2}$/, '')]?.id;
    }

    /** @override */
    async preCreate(args) {
        const { itemSource, pendingItems, context, ruleSource } = args;

        if (context.ptuStarterTraining && isStarterTrainingGrant(this.item) && hasStarterTraining(this.actor)) {
            const index = pendingItems.indexOf(itemSource);
            if (index >= 0) pendingItems.splice(index, 1);
            return;
        }

        if (this.reevaluateOnUpdate && this.predicate.length === 0) {
            ruleSource.ignored = true;
            return this.failValidation("`reevaluateOnUpdate` may only be used with a predicate.");
        }

        const uuid = this.resolveInjectedProperties(this.uuid);
        if (isExcludedContent(uuid)) {
            ui.notifications.warn('PTU | A new grant targets excluded compendium content and was not acquired.');
            return;
        }
        const grantedItem = await (async () => {
            try {
                return (await fromUuid(uuid))?.clone(this.overwrites ?? {}) ?? null;
            }
            catch (error) {
                console.error(error);
                return null;
            }
        })();
        if (!(grantedItem instanceof PTUItem)) return;

        ruleSource.flag =
            typeof ruleSource.flag === "string" && ruleSource.flag.length > 0
                ? ruleSource.flag
                : (() => {
                    const defaultFlag = grantedItem.slug ?? grantedItem.name;
                    const flagPattern = new RegExp(`^${defaultFlag}\\d*$`);
                    const itemGrants = itemSource.flags?.ptu?.itemGrants ?? {};
                    const nthGrant = Object.keys(itemGrants).filter((g => flagPattern.test(g))).length;
                    return nthGrant > 0 ? `${defaultFlag}${nthGrant + 1}` : defaultFlag;
                })();
        this.flag = String(ruleSource.flag);

        if (!this.test()) return;

        const migrations = MigrationList.constructFromVersion(grantedItem.schemaVersion);
        if (migrations.length) {
            await MigrationRunner.ensureSchemaVersion(grantedItem, migrations);
        }

        const acquiredUuid=compendiumItemIdentity(uuid);
        const existingItem = this.actor.items.find((i) => i.sourceId === uuid || (acquiredUuid&&compendiumItemIdentity(i.sourceId)===acquiredUuid) || (grantedItem.type === "condition" && i.slug === grantedItem.slug));
        if (!this.allowduplicate && existingItem) {
            if (this.replaceSelf) {
                const index = pendingItems.indexOf(isStarterTrainingGrant(this.item) ? itemSource : existingItem);
                if (index >= 0) pendingItems.splice(index, 1);
            }
            //this.#setGrantFlags(itemSource, existingItem);

            return args.reevaluation ? null : ui.notifications.warn(`Item ${grantedItem.name} is already granted to ${this.actor.name}.`);
        }

        if (!this.actor?.allowedItemTypes.includes(grantedItem.type)) {
            ui.notifications.error(`PTU | ${grantedItem.type} cannot be added to ${this.actor?.name}`);
            return [];
        }

        itemSource._id ??= foundry.utils.randomID();
        const grantedSource = grantedItem.toObject();
        grantedSource._id = foundry.utils.randomID();
        if(acquiredUuid){
            grantedSource._stats??={};
            grantedSource._stats.compendiumSource=acquiredUuid;
        }

        if (["feat", "edge"].includes(grantedSource.type) && !isStarterTrainingGrant(this.item)) {
            grantedSource.system.free = true;
        }
        if (isStarterTrainingGrant(this.item)) {
            // Trainer max already includes the extra slot; retain four ordinary starting choices.
            grantedSource.system.free = false;
            grantedSource._stats ??= {};
            grantedSource._stats.compendiumSource = uuid;
        }

        // Guarantee future alreadyGranted checks pass in all cases by re-assigning sourceId
        grantedSource.flags = foundry.utils.mergeObject(grantedSource.flags, { core: { sourceId: uuid } });

        // Create a temporary owned item and run its actor-data preparation and early-stage rule-element callbacks
        const tempGranted = new PTUItem(foundry.utils.deepClone(grantedSource), { parent: this.actor });

        tempGranted.prepareActorData?.();
        for (const rule of tempGranted.prepareRuleElements()) {
            rule.onApplyActiveEffects?.();
        }

        if (this.ignored) return;

        // If the granted item is replacing the granting item, swap it out and return early
        if (this.replaceSelf) {
            pendingItems.findSplice((i) => i === itemSource, grantedSource);
            await this.#runGrantedItemPreCreates(args, tempGranted, grantedSource, context);
            return;
        }

        context.keepId = true;

        this.#setGrantFlags(itemSource, grantedSource);

        // Run the granted item's preCreate callbacks unless this is a pre-actor-update reevaluation
        if (!args.reevaluation) {
            await this.#runGrantedItemPreCreates(args, tempGranted, grantedSource, context);
        }

        pendingItems.push(grantedSource);
    }

    /** @override */

    #getOnDeleteActions(source) {
        const actions = source.onDeleteActions;
        if (typeof actions === "object") {
            const ACTIONS = GrantItemRuleElement.ON_DELETE_ACTIONS;
            return ACTIONS.includes(actions.granter) || ACTIONS.includes(actions.grantee)
                ? actions : null;
        }
    }

    #setGrantFlags(granter, grantee) {
        const flags = foundry.utils.mergeObject(granter.flags ?? {}, { ptu: { itemGrants: {} } });
        if (!this.flag) throw new Error("GrantItemRuleElement#flag must be set before calling #setGrantFlags");
        flags.ptu.itemGrants[this.flag] = {
            id: grantee instanceof PTUItem ? grantee.id : grantee._id,
            // The on-delete action determines what will happen to the granter item when the granted item is deleted:
            // Default to "detach" (do nothing).
            onDelete: this.onDeleteActions?.grantee ?? "detach"
        }

        // The granted item records its granting item's ID at `flags.ptu.grantedBy`
        const grantedBy = {
            id: granter._id,
            // The on-delete action determines what will happen to the granted item when the granter item is deleted:
            // Default to "cascade" (delete the granted item)
            onDelete: this.onDeleteActions?.granter ?? "cascade"
        }

        if (grantee instanceof PTUItem) {
            // This is a previously granted item: update its grantedBy flag
            grantee.update({ "flags.ptu.grantedBy": grantedBy }, { render: false });
        }
        else {
            grantee.flags = foundry.utils.mergeObject(grantee.flags ?? {}, { ptu: { grantedBy } });
        }
    }

    async #runGrantedItemPreCreates(args, grantedItem, grantedSource, context) {
        for (const rule of grantedItem.rules) {
            const ruleSource = grantedSource.system.rules[grantedItem.rules.indexOf(rule)];
            await rule.preCreate?.({ ...args, itemSource: grantedSource, context, ruleSource });
        }
    }
